window.kbPageData["views/entry/k-b3ab2a226c13dbb0"] = {"key":"entry/k-b3ab2a226c13dbb0","state":{"route":"entry/k-b3ab2a226c13dbb0"},"node":{"id":"k-b3ab2a226c13dbb0","mode":"k","title":"历史黑土地的保护修复范围","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["历史上属黑土地的原则上纳入保护修复范围，确无法修复的除外"],"qs":["国考 2024 地市级 行测#8"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"国务院农业农村主管部门会同自然资源、水行政等有关部门确定并适时调整黑土地保护范围。历史上属黑土地的，原则上应纳入保护范围进行修复，确无法修复的除外。","review":{"definition":"国务院农业农村主管部门会同自然资源、水行政等有关部门确定并适时调整黑土地保护范围。历史上属黑土地的，原则上应纳入保护范围进行修复，确无法修复的除外。","explanation":"全国人大常委会公报第四条第二款写作“进行修复”，农业农村部转载网页写作“进行修恢复”。B项的“不列入……进行修复”可按该款的修复例外理解，条文免除了对确无法修复地块原则上应纳入修复范围的要求。选非题选D，因为第二十一条允许确需占用黑土地的建设项目依法严格审批，并补充数量和质量相当的耕地。","references":[{"source":"web-d06742b1a06210f4","location":"第四条第二款、第二十一条第一款","quote":"原则上都应列入黑土地保护范围进行修复"},{"source":"web-cf4e0dba8e83ecfb","location":"第四条第二款末句","quote":"进行修恢复"}],"evidence":"无法修复的黑土地不列入黑土地保护范围进行修复","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2024 地市级 行测#8":{"paper":"国考 2024 地市级 行测","n":8,"mod":"常识判断","src":["92d0b72e86a6a33d568d.pdf",2],"asrc":["e1792c53900a45f1b9fa.pdf",3],"card":"6e3890e42c8f30a94ea772a1","links":[{"id":"k-b3ab2a226c13dbb0","role":"直接考查","why":"第四条第二款明确了历史黑土地纳入保护修复范围的原则和例外。"}]}},"terms":{},"references":{"web-d06742b1a06210f4":{"name":"《全国人民代表大会常务委员会公报》2022年第4号《中华人民共和国黑土地保护法》","url":"https://npcobserver.com/wp-content/uploads/2023/10/2022-Black-Soil-Protection-Law_Gazette.pdf"},"web-cf4e0dba8e83ecfb":{"name":"农业农村部《中华人民共和国黑土地保护法》","url":"https://fgs.moa.gov.cn/flfg/202207/t20220712_6404544.htm"}},"topics":[],"units":{"k-b3ab2a226c13dbb0":[["国考 2024 地市级 行测#8"]]}};
